def handle(query, state):
    import shlex, re

    # Virtual filesystem lives in state
    vfs = state.get('files', {})

    def run_cmd(argv):
        """Simulate a tiny set of POSIX commands against the virtual filesystem."""
        if not argv:
            return ''
        cmd = argv[0]
        args = argv[1:]
        if cmd == 'ping':
            # -c N host  or just host
            host = args[-1] if args else ''
            # Validate host looks safe (no injection chars) — purely cosmetic
            if not re.match(r'^[A-Za-z0-9._-]+$', host):
                return 'ping: bad address\n'
            return f'PING {host}: 56 data bytes\n64 bytes from {host}: icmp_seq=0 ttl=64 time=1.23 ms\n'
        elif cmd == 'cat':
            out = ''
            for path in args:
                content = vfs.get(path)
                if content is None:
                    out += f'cat: {path}: No such file or directory\n'
                else:
                    out += content
                    if not content.endswith('\n'):
                        out += '\n'
            return out
        elif cmd == 'echo':
            return ' '.join(args) + '\n'
        elif cmd == 'ls':
            path = args[0] if args else '/'
            entries = [k for k in vfs if k.startswith(path)]
            return '\n'.join(entries) + '\n' if entries else 'ls: no entries\n'
        else:
            return f'{cmd}: command not found\n'

    def shell_exec(cmdline):
        """Split on ';' and run each segment in sequence, concatenating output.
        Does NOT support $() or backtick expansion."""
        output = ''
        for segment in cmdline.split(';'):
            segment = segment.strip()
            if not segment:
                continue
            try:
                argv = shlex.split(segment)
            except ValueError:
                argv = segment.split()
            output += run_cmd(argv)
        return output

    host = (query.get('host') or [''])[0]
    if not host:
        body = 'Usage: ?host=<hostname>\n'
        return 200, {'Content-Type': 'text/plain'}, body

    # The vulnerable call: host is passed unsanitised into the shell emulator
    output = shell_exec('ping -c 4 ' + host)
    return 200, {'Content-Type': 'text/plain'}, output
